set-variable.value:
@{
    var jwt = (Jwt)context.Variables["riversideClientJwt"];
    return jwt.Claims.GetValueOrDefault("oid", jwt.Claims.GetValueOrDefault("sub", string.Empty));
  }

return-response.set-body:
@{
          return new JObject(
            new JProperty("error", new JObject(
              new JProperty("code", "forbidden"),
              new JProperty("message", "Required authorization context is unavailable."),
              new JProperty("type", "authorization_error"),
              new JProperty("param", null),
              new JProperty("retryable", false))),
            new JProperty("trace", new JObject(
              new JProperty("trace_id", (string)context.Variables["riversideTraceId"]),
              new JProperty("retry_count", 0)))
          ).ToString(Newtonsoft.Json.Formatting.None);
        }
